// Recebe os dados do endereço
const rua = $input.item.json.rua || '';
const numero = $input.item.json.numero || '';
const bairro = $input.item.json.bairro || '';
const cidade = 'Montes Claros';
const estado = 'MG';

// Validação básica
if (!rua || !numero || !bairro) {
  return {
    sucesso: false,
    erro: 'Dados incompletos. Envie: rua, numero e bairro',
    mensagem: 'Por favor, informe o endereço completo: rua, número e bairro'
  };
}

// Normaliza o nome do bairro (remove acentos, lowercase)
const normalizarTexto = (texto) => {
  return texto
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .trim();
};

const bairroNormalizado = normalizarTexto(bairro);

// Retorna os dados processados
return {
  endereco_completo: `${rua}, ${numero} - ${bairro}, ${cidade}/${estado}`,
  rua: rua.trim(),
  numero: numero.toString().trim(),
  bairro: bairro.trim(),
  bairro_normalizado: bairroNormalizado,
  cidade,
  estado,
  validado: true
};

// Tabela de frete por bairro de Montes Claros, MG
// VOCÊ PODE CUSTOMIZAR OS VALORES E ADICIONAR MAIS BAIRROS
const tabelaFrete = {
  // Zona Central - Frete mais barato
  'centro': 10.00,
  'vila guilhermina': 10.00,
  'todos os santos': 12.00,
  'sao jose': 12.00,
  'morrinhos': 12.00,

  // Zona Norte
  'major prates': 15.00,
  'jardim panorama': 15.00,
  'sao luiz': 15.00,
  'jardim sao luiz': 15.00,
  'ibituruna': 18.00,

  // Zona Sul
  'santo expedito': 15.00,
  'sao judas tadeu': 15.00,
  'cidade nova': 15.00,
  'independencia': 15.00,
  'melo': 18.00,

  // Zona Leste
  'alterosa': 18.00,
  'jardim alterosa': 18.00,
  'planalto': 20.00,
  'ciro dos anjos': 20.00,

  // Zona Oeste
  'maracanã': 18.00,
  'sumaré': 18.00,
  'canelas': 20.00,
  'santa rita': 20.00,
  'vila atletico': 18.00,

  // Bairros mais distantes
  'distrito industrial': 25.00,
  'village do lago': 25.00,
  'santa eugenia': 22.00,
  'jardim brasil': 22.00,
  'bela vista': 20.00,
  'sagrada familia': 18.00,
  'carmelo': 20.00,
  'roxo verde': 22.00
};

// Pega os dados validados do node anterior
const item = $input.item.json;

// Se houve erro na validação, retorna o erro
if (item.sucesso === false) {
  return item;
}

const bairroNormalizado = item.bairro_normalizado;

// Busca o valor do frete na tabela
let valorFrete = tabelaFrete[bairroNormalizado];

// Se o bairro não está na tabela, usa valor padrão
if (valorFrete === undefined) {
  valorFrete = 20.00; // Valor padrão para bairros não cadastrados

  return {
    sucesso: true,
    endereco_completo: item.endereco_completo,
    rua: item.rua,
    numero: item.numero,
    bairro: item.bairro,
    cidade: item.cidade,
    estado: item.estado,
    valor_frete: valorFrete,
    aviso: `Bairro "${item.bairro}" não encontrado na tabela. Aplicado valor padrão.`,
    mensagem: `Frete calculado com sucesso! Valor: R$ ${valorFrete.toFixed(2)}`
  };
}

// Retorna o resultado com o valor do frete
return {
  sucesso: true,
  endereco_completo: item.endereco_completo,
  rua: item.rua,
  numero: item.numero,
  bairro: item.bairro,
  cidade: item.cidade,
  estado: item.estado,
  valor_frete: valorFrete,
  mensagem: `Frete calculado com sucesso! Valor: R$ ${valorFrete.toFixed(2)}`
};
